:root {
  --bg-card: #0d1117;
  --bg-header: #161b22;
  --bg-panel: #1a2030;
  --bg-footer: #161b22;
  --border-main: #2a3550;
  --border-accent: #3b5bdb;
  --text-primary: #e6edf3;
  --text-secondary: #8b949e;
  --text-muted: #4a5568;
  --badge-active-bg: #1a3a2a;
  --badge-active-text: #3fb950;
  --badge-active-border: #2ea043;
  --type-globular-bg: #2d1f5e;
  --type-globular-text: #c084fc;
  --type-nebula-bg: #1a2f4a;
  --type-nebula-text: #60a5fa;
  --type-galaxy-bg: #3a1f1f;
  --type-galaxy-text: #f87171;
  --rating-color: #f59e0b;
  --btn-bg: #3b5bdb;
  --btn-text: #ffffff;
  --btn-hover: #2f4ec0;
}

.obs-log {
  background: var(--bg-card);
  border: 1px solid var(--border-main);
  border-radius: 14px;
  width: 480px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
}

.log-header {
  background: var(--bg-header);
  border-bottom: 1px solid var(--border-main);
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 16px;
}

.header-left {
  display: flex;
  align-items: center;
  gap: 10px;
}

.obs-icon {
  font-size: 26px;
  line-height: 1;
}

.obs-title {
  font-size: 16px;
  font-weight: 700;
  color: var(--text-primary);
  margin: 0;
  line-height: 1.2;
}

.obs-subtitle {
  font-size: 11px;
  color: var(--text-secondary);
  margin: 2px 0 0 0;
}

.header-right {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 4px;
}

.status-badge {
  background: var(--badge-active-bg);
  color: var(--badge-active-text);
  border: 1px solid var(--badge-active-border);
  border-radius: 20px;
  font-size: 10px;
  font-weight: 700;
  padding: 2px 9px;
  letter-spacing: 0.08em;
}

.log-date {
  font-size: 11px;
  color: var(--text-secondary);
  margin: 0;
}

.log-body {
  display: grid;
  grid-template-columns: 164px 1fr;
  gap: 0;
  flex: 1;
}

.conditions-panel {
  background: var(--bg-panel);
  border-right: 1px solid var(--border-main);
  padding: 12px;
}

.panel-label {
  font-size: 10px;
  font-weight: 700;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.1em;
  margin: 0 0 10px 0;
}

.conditions-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.cond-item {
  display: flex;
  align-items: center;
  gap: 7px;
  background: var(--bg-card);
  border: 1px solid var(--border-main);
  border-radius: 8px;
  padding: 6px 8px;
}

.cond-icon {
  font-size: 14px;
  line-height: 1;
}

.cond-name {
  font-size: 11px;
  color: var(--text-secondary);
  flex: 1;
}

.cond-val {
  font-size: 12px;
  font-weight: 700;
  color: var(--text-primary);
}

.targets-panel {
  padding: 12px;
  background: var(--bg-card);
}

.target-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.target-row {
  display: grid;
  grid-template-columns: 64px 1fr auto auto;
  align-items: center;
  gap: 8px;
  background: var(--bg-panel);
  border: 1px solid var(--border-main);
  border-radius: 8px;
  padding: 6px 10px;
}

.target-id {
  font-size: 11px;
  font-weight: 700;
  color: var(--border-accent);
  font-variant-numeric: tabular-nums;
}

.target-name {
  font-size: 12px;
  color: var(--text-primary);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.target-type {
  font-size: 10px;
  font-weight: 600;
  border-radius: 4px;
  padding: 2px 6px;
}

.target-type.globular {
  background: var(--type-globular-bg);
  color: var(--type-globular-text);
}

.target-type.nebula {
  background: var(--type-nebula-bg);
  color: var(--type-nebula-text);
}

.target-type.galaxy {
  background: var(--type-galaxy-bg);
  color: var(--type-galaxy-text);
}

.target-rating {
  font-size: 11px;
  color: var(--rating-color);
  letter-spacing: -1px;
}

.log-footer {
  background: var(--bg-footer);
  border-top: 1px solid var(--border-main);
  display: flex;
  align-items: center;
  padding: 10px 16px;
  gap: 0;
}

.scope-info {
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding: 0 14px;
}

.scope-info:first-child {
  padding-left: 0;
}

.scope-label {
  font-size: 10px;
  color: var(--text-muted);
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
}

.scope-val {
  font-size: 12px;
  font-weight: 600;
  color: var(--text-primary);
}

.divider-v {
  width: 1px;
  height: 32px;
  background: var(--border-main);
}

.export-btn {
  margin-left: auto;
  background: var(--btn-bg);
  color: var(--btn-text);
  border: none;
  border-radius: 8px;
  font-size: 12px;
  font-weight: 700;
  padding: 7px 14px;
  cursor: pointer;
}
